describe('Password Requirements Tooltip', () => {
  beforeEach(() => {
    cy.visit('/');
    cy.get('input[type="password"]').as('passwordInput');
  });

  it('should display tooltip with password requirements on focus', () => {
    cy.get('@passwordInput').focus();
    cy.get('[role="tooltip"]').should('be.visible');
    cy.get('[role="tooltip"]').should('contain', 'Password must be at least 8 characters');
    cy.get('[role="tooltip"]').should('contain', 'Must include uppercase letter');
    cy.get('[role="tooltip"]').should('contain', 'Must include lowercase letter');
    cy.get('[role="tooltip"]').should('contain', 'Must include number');
    cy.get('[role="tooltip"]').should('contain', 'Must include special character');
  });

  it('should hide tooltip when password input loses focus', () => {
    cy.get('@passwordInput').focus();
    cy.get('[role="tooltip"]').should('be.visible');
    cy.get('@passwordInput').blur();
    cy.get('[role="tooltip"]').should('not.be.visible');
  });

  it('should display tooltip on hover over password field info icon', () => {
    cy.get('button[aria-label="password requirements info"]').trigger('mouseenter');
    cy.get('[role="tooltip"]').should('be.visible');
    cy.get('[role="tooltip"]').should('have.text', 'Password must contain at least 8 characters, one uppercase letter, one lowercase letter, one number, and one special character');
  });

  it('should hide tooltip when hovering away from info icon', () => {
    cy.get('button[aria-label="password requirements info"]').trigger('mouseenter');
    cy.get('[role="tooltip"]').should('be.visible');
    cy.get('button[aria-label="password requirements info"]').trigger('mouseleave');
    cy.get('[role="tooltip"]').should('not.be.visible');
  });

  it('should update tooltip styling based on password validity', () => {
    cy.get('@passwordInput').focus();
    cy.get('[role="tooltip"]').should('have.class', 'tooltip-invalid');
    cy.get('@passwordInput').type('ValidPass123!');
    cy.get('[role="tooltip"]').should('have.class', 'tooltip-valid');
  });

  it('should display tooltip on mobile devices with touch interaction', () => {
    cy.viewport('iphone-x');
    cy.get('@passwordInput').click();
    cy.get('[role="tooltip"]').should('be.visible');
    cy.get('[role="tooltip"]').should('contain', 'Password must be at least 8 characters');
  });

  it('should handle tooltip positioning without overflow on small screens', () => {
    cy.viewport(320, 568);
    cy.get('@passwordInput').focus();
    cy.get('[role="tooltip"]').should('be.visible');
    cy.get('[role="tooltip"]').then(($tooltip) => {
      const rect = $tooltip[0].getBoundingClientRect();
      expect(rect.right).to.be.lessThan(window.innerWidth);
      expect(rect.left).to.be.greaterThan(0);
    });
  });

  it('should persist tooltip when interacting with password field', () => {
    cy.get('@passwordInput').focus();
    cy.get('[role="tooltip"]').should('be.visible');
    cy.get('@passwordInput').type('Test');
    cy.get('[role="tooltip"]').should('be.visible');
    cy.get('@passwordInput').clear();
    cy.get('[role="tooltip"]').should('be.visible');
  });

  it('should not display tooltip for non-password input fields', () => {
    cy.get('input[type="text"]').first().focus();
    cy.get('[role="tooltip"]').should('not.exist');
  });
});
